import 'dart:convert';
class ExpansionSaveManager { static const schemaVersion=2; Map<String,dynamic> encode(Map<String,dynamic> legacy,Map<String,dynamic> expansion)=>{'saveSchema':schemaVersion,'legacy':legacy,'expansion':expansion}; String stringify(Map<String,dynamic> legacy,Map<String,dynamic> expansion)=>jsonEncode(encode(legacy,expansion)); Map<String,dynamic>? decode(String raw){try{final parsed=jsonDecode(raw);if(parsed is! Map)return null;if(parsed['legacy'] is Map)return Map<String,dynamic>.from(parsed);return {'saveSchema':0,'legacy':Map<String,dynamic>.from(parsed),'expansion':<String,dynamic>{}};}catch(_){return null;}} }
